[ImplicitStreamSubscription("TESTDATA")]
public class EngagmentGrain : Grain, IEngagementGrain, IAsyncObserver<string>
{
    protected StreamSubscriptionHandle<string> _sub;

    public Task<string> Test(string input)
    {
        return Task.FromResult($"you said {input}. i say hello!");
    }

    public override async Task OnActivateAsync()
    {
        var guid = this.GetPrimaryKey();
        var streamProvider = GetStreamProvider("AZQProvider");
        var stream = streamProvider.GetStream<string>(guid, "TESTDATA");
        _sub = await stream.SubscribeAsync(this);            
    }

    public override async Task OnDeactivateAsync()
    {
        if (_sub != null)
            await _sub.UnsubscribeAsync();
    }

