Resolved by #3128, I tested the fix locally using a private build. That required upgrading the sample project to my 1.5.0 build and changing the client to match the upgraded Service Fabric support:
```C#
namespace Audit.OrleansTest.Terminal
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            Console.WriteLine("Press any key once service is ready...");
            Console.ReadKey();

            var serviceName = new Uri("fabric:/Audit.OrleansTest/Audit.OrleansTest.Service");
            var config = new ClientConfiguration
            {
                DeploymentId = Regex.Replace(serviceName.PathAndQuery.Trim('/'), "[^a-zA-Z0-9_]", "_")
            };
            config.AddAzureQueueStreamProvider("AZQProvider", "UseDevelopmentStorage=true", deploymentId: "orleanstestqueue");
            var builder = new ClientBuilder().UseConfiguration(config).AddServiceFabric(serviceName);
            var client = builder.Build();
            client.Connect().Wait();
            var id = Guid.NewGuid();
            var streamProvider = client.GetStreamProvider("AZQProvider");            
            var stream = streamProvider.GetStream<string>(id, "TESTDATA");
            stream.OnNextAsync("testing123").Wait();
            Console.WriteLine($"Published to stream TESTDATA id {id}");
            Console.ReadKey();
        }
    }
}
```
